insert into public.content_blocks (key, value, schema_version) values
  ('PERSONALITY_BY_MONTH_GOD', $json${"비견":"사회에서는 누구에게 기대기보다 스스로 해내려는 모습이 두드러져요. 주변 사람을 윗사람이나 아랫사람보다 형제 같은 동등한 동료로 대하는 편이에요. 내 몫과 원칙을 분명히 해서 믿음직하다는 말을 듣지만, 도움을 청하는 데는 서툴 수 있어요. 혼자 감당하기 벅찰 때 먼저 손을 내밀어보면, 기꺼이 도와주는 사람이 생각보다 많다는 걸 알게 돼요.","겁재":"사회에서는 승부욕과 추진력이 먼저 보이는 편이에요. 경쟁이 있는 환경에서 오히려 힘이 나고, 목표가 생기면 빠르게 움직여 분위기를 주도해요. 의욕이 앞설 때는 씀씀이가 커지거나 사람을 쉽게 믿기 쉬워서, 돈과 사람 관계는 한 번 더 살피는 게 좋아요. 중요한 결정은 하루 묵혀 다시 보고, 혼자 다 떠안으려는 마음을 조금 내려놓으면 추진력이 온전히 장점으로 남아요.","식신":"사회에서는 여유 있고 편안한 사람으로 보이기 쉬워요. 마음이 너그럽고 서두르지 않아서, 제 속도로 차근차근 실력을 쌓는 편이에요. 좋아하는 일을 꾸준히 하다 보면 자연스럽게 결과가 따라오고, 주변 분위기를 부드럽게 만드는 힘이 있어요. 편안함에 머물러 새로운 시도를 미루기 쉬우니, 가끔은 일부러 낯선 일에 도전해보면 재능의 폭이 넓어져요.","상관":"사회에서는 재치 있고 아이디어가 많은 사람으로 보이기 쉬워요. 재주가 많고 자존심도 높은 편이라, 남다른 감각으로 새로운 방법을 찾아내는 데 강해요. 틀에 박힌 방식을 답답해하고 할 말은 하는 편이라, 능력을 인정받는 동시에 까다롭다는 말을 들을 수도 있어요. 상대의 방식에도 이유가 있다는 걸 먼저 인정해주고 말하면, 날카로운 의견이 훨씬 잘 받아들여져요.","편재":"사회에서는 발이 넓고 기회를 잘 알아보는 사람으로 보이기 쉬워요. 사람들 사이를 오가며 일과 기회를 연결하는 데 능하고, 움직이는 만큼 성과가 따라와요. 통이 커서 주변에 베푸는 것도 좋아하고, 여럿이 함께 나누는 자리에서 존재감이 커져요. 들어오고 나가는 흐름이 큰 편이니, 내 몫을 따로 챙겨두는 습관을 들이면 넉넉함이 오래 가요.","정재":"사회에서는 꼼꼼하고 성실한 사람으로 보이기 쉬워요. 계획을 세워 차근차근 해내는 데 강하고, 약속한 것은 지키려 해서 믿고 맡길 수 있다는 평을 듣는 편이에요. 무리해서 크게 벌이기보다, 감당할 만큼을 때에 맞게 정확히 해내는 방식이 잘 맞아요. 안정을 중시하다 기회 앞에서 망설일 수 있으니, 작은 범위에서 먼저 시도해보는 연습이 도움이 돼요.","편관":"사회에서는 강단 있고 위기에 강한 사람으로 보이기 쉬워요. 부담이 큰 자리에서 오히려 집중력이 올라가고, 어려운 일을 맡아 해결하면서 인정받는 편이에요. 이 힘을 잘 다스릴수록 크게 이루는 타입이라, 압박을 성장의 계기로 바꾸는 요령이 중요해요. 스스로에게 엄격해 긴장을 놓지 못하기 쉬우니, 쉬는 시간을 일정처럼 챙겨두면 힘을 오래 쓸 수 있어요.","정관":"사회에서는 책임감 있고 믿음직한 사람으로 보이기 쉬워요. 질서 있고 안정된 환경에서 실력이 잘 드러나고, 흔들리고 부딪히는 상황은 유독 불편해하는 편이에요. 정해진 규칙과 약속을 지키는 데서 편안함을 느끼고, 맡은 역할을 끝까지 해내려 해요. 원칙을 지키려다 융통성이 없어 보일 수 있으니, 상황에 따라 한 걸음 양보하는 여유를 곁들이면 신뢰가 더 깊어져요.","편인":"사회에서는 독특한 시선과 깊은 생각을 가진 사람으로 보이기 쉬워요. 남들이 지나치는 부분을 파고드는 힘이 있고, 혼자 몰입할 수 있는 환경에서 실력이 잘 나와요. 관심사가 다양해 하나를 마치기 전에 다음 것으로 마음이 옮겨가기 쉬워서, 시작에 비해 끝맺음이 약해질 수 있어요. 한 번에 하나씩 작게 끝내는 습관을 들이면, 깊은 생각이 눈에 보이는 결과로 바뀌어요.","정인":"사회에서는 차분하고 배움이 깊은 사람으로 보이기 쉬워요. 생각이 깊고 마음이 넉넉해서, 주변과 서로 돕고 이끌어주는 관계를 잘 만들어요. 도움과 신뢰를 잘 얻는 편이고, 배운 것을 바탕으로 안정적으로 자리를 잡아가요. 받는 데 익숙해져 스스로 나서는 일을 미루기 쉬우니, 배운 것을 직접 써보고 나누는 기회를 만들면 실력이 한층 단단해져요."}$json$::jsonb, 1),
  ('WEALTH_BY_JAESEONG', $json${"none":"사주에 재물을 뜻하는 기운이 겉으로 드러나 있지 않아요. 그렇다고 재물이 없다는 뜻은 아니고, 돈보다 일의 의미나 사람을 먼저 보는 성향으로 나타나기 쉬워요. 돈 자체를 목표로 삼기보다 실력과 경험을 쌓다 보면 따라오는 흐름에 가까워요. 다만 돈 관리에는 관심이 덜 가기 쉬우니, 들어오고 나가는 돈을 기록하고 저축을 먼저 떼어두는 습관이 특히 도움이 돼요.","some":"사주에 재물을 뜻하는 기운이 알맞게 있어, 돈을 보는 감각과 현실적인 균형이 있는 편이에요. 재물은 많은 것보다 때에 맞게 있는 것이 좋다고 하는데, 지금 구성이 그 말에 가까워요. 필요한 만큼 벌고 쓸 줄 알아서, 무리한 욕심 없이 생활을 꾸려가는 힘이 있어요. 한 번에 크게 불리려 하기보다 꾸준히 모으는 방식이 가장 잘 맞고, 안정된 기반 위에서 조금씩 넓혀가면 좋아요.","many":"사주에 재물을 뜻하는 기운이 여러 개 있어, 돈과 기회에 대한 감각이 예민한 편이에요. 눈앞에 기회가 많이 보이고, 여러 일을 동시에 벌이기 쉬운 타입이에요. 재물의 기운이 많을수록 그것을 감당할 내 힘이 받쳐줘야 해요. 기회가 많아도 체력과 시간이 따라주지 않으면 다 잡기 어렵기 때문이에요. 그래서 벌이는 것만큼 정리하고 지키는 계획을 함께 세우고, 감당할 수 있는 만큼만 고르는 습관을 들이면 좋아요."}$json$::jsonb, 1),
  ('LOVE_BY_DAY_GOD', $json${"비견":"연애에서는 친구처럼 대등하고 편한 관계를 원하는 편이에요. 서로의 영역을 존중해주는 사람과 잘 맞고, 함께 있어도 각자의 시간과 취향을 지킬 수 있을 때 마음이 편안해요. 좋아하는 것을 같이 즐기는 동료 같은 사이에서 애정이 깊어지기 쉬워요. 둘 다 자기 주장이 분명해 사소한 일로 팽팽해질 수 있으니, 누가 옳은지보다 어떻게 맞출지를 먼저 이야기하면 관계가 한결 부드러워져요.","겁재":"연애에서는 함께 도전하고 자극을 주고받는 관계에 끌리는 편이에요. 감정 표현이 솔직하고 뜨거워서 가까워지는 속도가 빠르지만, 그만큼 부딪힐 때도 세게 부딪히기 쉬워요. 다툼이 생기면 이기려 하기보다 한 걸음 물러서는 여유가 관계를 지켜줘요. 돈 문제는 미리 기준을 정해두면 서로 서운할 일이 줄어들어요.","식신":"연애에서는 함께 먹고 쉬고 웃는 편안한 관계를 원하는 편이에요. 자극보다 일상의 즐거움을 나눌 수 있는 사람과 잘 맞아요. 상대를 편하게 해주는 넉넉함이 있어 곁에 있으면 마음이 놓인다는 말을 듣기 쉬워요. 편안함에 익숙해져 표현이 줄어들 수 있으니, 가끔은 작은 이벤트나 고마움의 말로 마음을 전해보세요.","상관":"연애에서는 대화가 잘 통하고 재미있는 관계를 중요하게 여기는 편이에요. 감정과 생각을 숨기지 않고 표현해서 관계에 활기가 있어요. 기대가 높은 만큼 상대의 부족한 점이 눈에 잘 들어오기도 해요. 솔직한 말이 상처가 되지 않도록 표현을 한 번 다듬고, 고쳐줬으면 하는 점보다 좋은 점을 먼저 말해주면 사이가 훨씬 깊어져요.","편재":"연애에서는 활동적이고 새로운 경험을 함께할 수 있는 관계에 끌리는 편이에요. 상대에게 통 크게 잘해주고 함께 즐기는 시간을 소중히 여겨요. 사람을 좋아하고 바깥 활동이 많아 상대가 서운해할 수 있으니, 둘만의 시간을 따로 정해두면 좋아요. 즐거움이 큰 만큼 서로의 생활 리듬을 맞추는 대화가 도움이 돼요.","정재":"연애에서는 성실하고 믿을 수 있는 안정적인 관계를 원하는 편이에요. 말보다 행동으로 꾸준히 챙기는 타입이라, 시간이 지날수록 신뢰가 쌓이는 관계를 만들어요. 생활을 함께 꾸려가는 계획을 나누며 가까워지기 쉬워요. 마음을 표현하는 데는 서툴 수 있으니, 가끔은 고마움과 애정을 말로도 전해보세요.","편관":"연애에서는 강단 있고 카리스마 있는 사람에게 끌리기 쉬워요. 관계에서도 책임감이 강해 상대를 지키고 이끌려는 마음이 커요. 서로 기준이 높아 긴장감이 생기기 쉬우니, 잘잘못을 따지기보다 솔직하게 마음을 나누는 시간이 큰 힘이 돼요. 편하게 풀어져도 괜찮은 관계라는 믿음이 생기면 사이가 한결 깊어져요.","정관":"연애에서는 예의 바르고 책임감 있는 관계를 원하는 편이에요. 약속을 지키고 서로를 존중하는 모습에서 신뢰가 깊어져요. 오래 함께할 사람을 신중하게 고르는 타입이라, 시작은 느려도 한번 맺은 관계를 소중히 지켜요. 격식을 중시하다 보면 속마음을 꺼내는 데 시간이 걸릴 수 있으니, 가까운 사이일수록 편하게 기대는 연습을 해보면 좋아요.","편인":"연애에서는 생각이 통하고 서로의 개성을 이해해주는 관계를 원하는 편이에요. 혼자만의 시간도 존중해주는 사람과 편안해요. 깊은 대화를 나눌 수 있을 때 마음이 열리고, 남들과 다른 나만의 취향을 알아봐 주는 사람에게 끌려요. 속마음을 혼자 정리하느라 상대가 답답해할 수 있으니, 정리가 덜 됐더라도 지금 어떤 기분인지 짧게 알려주면 오해가 줄어요.","정인":"연애에서는 서로 챙기고 보살펴주는 안정적인 관계를 원하는 편이에요. 따뜻하게 돌봐주는 사람에게 마음이 가고, 나 역시 상대를 편안하게 품어주려 해요. 받는 배려에 익숙해지지 않도록 고마움을 자주 표현하면 좋아요. 기대고 싶은 마음이 클 때일수록 내가 먼저 해줄 수 있는 것을 찾아보면 관계의 균형이 잘 잡혀요."}$json$::jsonb, 1),
  ('CAREER_BY_GROUP', $json${"비겁":{"keywords":"자립심, 실행력, 책임감","body":"남에게 기대기보다 내 힘으로 결과를 만들어낼 때 가장 살아나는 타입이에요. 누가 정해준 길을 따라가기보다 스스로 판단하고 움직일 수 있는 일에서 의욕이 크게 올라요. 혼자서도 끝까지 해내는 뚝심이 있어 믿고 맡길 수 있다는 평을 듣기 쉽고, 뜻이 맞는 사람들과 팀을 이루면 앞장서서 분위기를 이끄는 역할도 잘해요. 다만 내 방식에 대한 확신이 강한 만큼, 다른 사람의 방식을 존중하는 여유를 곁들이면 더 넓은 무대를 함께 만들 수 있어요.","jobs":"프리랜서, 1인 창업, 운동·코칭, 현장 리더, 기술 전문직, 영업 팀장"},"식상":{"keywords":"표현력, 창의성, 손재주","body":"머릿속 생각을 말, 글, 작품, 기술로 꺼내 보일 때 가장 빛나는 타입이에요. 정해진 답을 반복하기보다 새로운 방식을 시도하고 결과물을 직접 만들어내는 일에서 보람을 느껴요. 사람들 앞에서 설명하거나 가르치는 일에도 재능이 있어, 내 생각이 누군가에게 전해질 때 큰 힘을 얻어요. 아이디어가 많은 만큼 벌여놓고 마무리가 늦어지기 쉬우니, 끝맺는 날짜를 먼저 정해두는 습관이 실력을 결과로 바꿔줘요.","jobs":"디자이너, 작가·콘텐츠 제작자, 요리사, 강사·교사, 기획자, 공예·기술직"},"재성":{"keywords":"현실 감각, 추진력, 협상력","body":"결과가 눈에 보이고 숫자로 확인되는 일에서 강점이 살아나는 타입이에요. 사람과 기회를 연결하고, 흩어진 자원을 모아 성과로 바꾸는 감각이 좋아요. 현실적인 판단이 빨라 어디에 힘을 쓰면 효과가 큰지 잘 알아보고, 협상이나 거래 자리에서도 손해 보지 않는 편이에요. 다만 여러 기회를 한꺼번에 잡으려다 힘이 분산되기 쉬우니, 가장 중요한 한두 가지에 집중하는 우선순위를 세우면 성과가 더 커져요.","jobs":"영업·마케팅, 유통·무역, 재무·회계, 투자·자산관리, 사업 운영, 부동산"},"관성":{"keywords":"책임감, 신뢰, 조직력","body":"규칙과 책임이 분명한 자리에서 믿음직하게 자리를 잡는 타입이에요. 맡은 역할을 끝까지 해내고 약속을 지키는 모습 덕분에 조직에서 신뢰를 얻기 쉬워요. 체계 안에서 차근차근 경력을 쌓아 올라가는 길과 잘 맞고, 사람과 일을 관리하고 기준을 세우는 역할에서도 능력을 보여요. 책임감이 큰 만큼 스스로에게 엄격해지기 쉬우니, 잘 해낸 일은 스스로 인정해주는 여유를 챙기면 오래 힘을 낼 수 있어요.","jobs":"공무원·공공기관, 기업 관리직, 법률·행정, 군인·경찰, 인사·총무, 품질·안전 관리"},"인성":{"keywords":"학습력, 깊이, 신중함","body":"배우고 이해하고 깊이 파고드는 일에서 가장 편안한 타입이에요. 한 분야를 꾸준히 공부해 전문성을 쌓는 데 강하고, 자격이나 지식이 실력의 바탕이 되는 일과 잘 맞아요. 주변의 도움과 신뢰를 잘 얻는 편이라 좋은 스승이나 선배를 만나면 성장 속도가 빨라져요. 생각이 깊은 만큼 시작이 늦어질 수 있으니, 준비가 덜 됐다 싶어도 작게 먼저 해보는 연습이 기회를 넓혀줘요.","jobs":"연구원, 교수·교사, 의료·보건 전문직, 상담사, 출판·편집, 전문 자격직"}}$json$::jsonb, 1),
  ('CAREER_BALANCED', $json${"keywords":"균형감, 적응력, 다재다능","body":"타고난 기운이 한쪽으로 크게 쏠리지 않아, 어느 한 분야에 묶이기보다 여러 역할에 고르게 적응하는 타입이에요. 상황에 따라 앞에 나서기도 하고 뒤에서 받쳐주기도 하는 유연함이 강점이에요. 다양한 경험을 쌓을수록 나에게 맞는 일이 또렷해지는 편이라, 관심 가는 일을 작게 여러 번 시도해보는 것이 좋아요. 여러 일을 두루 잘하는 만큼 하나의 대표 분야를 정해두면 사람들이 나를 기억하기 쉬워져요.","jobs":"기획·운영, 프로젝트 관리, 서비스업, 교육, 컨설팅, 여러 분야의 실무"}$json$::jsonb, 1),
  ('CAREER_TIP_BY_LACKING', $json${"비겁":"나를 받쳐주는 기운이 약한 편이라, 혼자 결정하고 밀고 나가야 하는 일은 부담이 될 수 있어요. 믿을 만한 동료나 멘토와 함께 의논하는 구조를 만들면 훨씬 힘이 덜 들어요. 작은 결정부터 스스로 정해보는 연습도 자신감을 키워줘요.","식상":"표현과 재능의 기운이 약한 편이라, 생각을 밖으로 꺼내 보이는 일은 연습이 필요할 수 있어요. 기록하거나 짧게 발표하는 습관을 들이면 실력이 제대로 평가받는 데 도움이 돼요. 결과물을 눈에 보이게 정리해두는 것도 좋은 방법이에요.","재성":"재물과 현실 감각의 기운이 약한 편이라, 일 자체에는 몰입해도 돈 계산이나 계약 조건은 뒤로 미루기 쉬워요. 단가 정하기, 정산, 계약서 확인 같은 실무는 꼼꼼한 동료나 도구의 도움을 받거나, 일을 시작하기 전에 체크리스트로 먼저 정해두면 좋아요.","관성":"규칙과 책임의 기운이 약한 편이라, 정해진 틀이나 마감이 없으면 일이 느슨해지기 쉬워요. 스스로 마감일을 정하고 진행 상황을 누군가와 공유하면 꾸준함이 훨씬 좋아져요.","인성":"배움과 안정의 기운이 약한 편이라, 깊이 준비하기보다 부딪히며 배우는 편이에요. 일이 익숙해질 때쯤 관련 공부나 자격을 한 번 정리해두면, 경험이 탄탄한 전문성으로 바뀌어요."}$json$::jsonb, 1),
  ('SINSAL', $json${"dohwa":{"name":"도화살","hanja":"桃花殺","title":"사람을 끄는 매력","body":"복숭아꽃처럼 사람들의 눈길을 모으는 기운이에요. 옛날에는 이성 문제를 조심하라는 뜻으로 풀었지만, 요즘은 매력과 인기, 표현력으로 봐요. 처음 만난 사람과도 금방 분위기를 만들고, 나를 드러내는 일에서 힘을 발휘하기 쉬워요."},"yeokma":{"name":"역마살","hanja":"驛馬殺","title":"움직이는 힘","body":"한곳에 머물기보다 움직이고 넓혀가는 기운이에요. 이동, 여행, 이사처럼 새로운 환경에 적응하는 힘이 좋아요. 반복되는 일상보다 활동 반경이 넓은 일에서 더 살아나는 편이에요."},"hwagae":{"name":"화개살","hanja":"華蓋殺","title":"혼자 깊어지는 시간","body":"화려한 덮개라는 뜻으로, 예술·학문·종교처럼 정신적인 세계에 끌리는 기운이에요. 혼자 생각을 정리하는 시간이 필요하고, 한 분야를 깊이 파고들어 자기만의 세계를 만드는 힘이 있어요."},"cheoneul":{"name":"천을귀인","hanja":"天乙貴人","title":"도움을 부르는 복","body":"신살 중 가장 좋은 길신으로 꼽혀요. 어려운 순간에 도와주는 사람이나 길이 나타나기 쉬운 기운이에요. 평소에 쌓은 인연이 중요한 순간에 힘이 되는 편이에요."},"munchang":{"name":"문창귀인","hanja":"文昌貴人","title":"글과 배움의 재능","body":"글, 공부, 시험, 말로 정리하는 일에 재능을 주는 기운이에요. 배운 것을 이해하기 쉽게 풀어내는 힘이 좋아서, 기록하거나 가르치는 일과 잘 맞아요."},"hongyeom":{"name":"홍염살","hanja":"紅艶殺","title":"은근한 감성과 멋","body":"감정 표현이 풍부하고 멋을 아는 기운이에요. 도화살이 밖으로 드러나는 매력이라면, 홍염살은 은근히 풍기는 분위기와 감수성에 가까워요. 꾸미는 일이나 예술적인 감각에서 재능이 드러나기 쉬워요."},"yangin":{"name":"양인살","hanja":"羊刃殺","title":"날카로운 결단력","body":"타고난 기운이 아주 강해지는 자리예요. 자기 주장이 분명하고 승부욕과 실행력이 뛰어나요. 힘이 센 만큼 부딪히는 일이 생기기 쉬우니, 한 박자 쉬고 말하는 습관이 큰 도움이 돼요."},"baekho":{"name":"백호살","hanja":"白虎殺","title":"강한 추진력","body":"기운이 세고 결단이 빠른 성향이에요. 옛날에는 사고를 조심하라는 뜻으로 무섭게 풀었지만, 요즘은 밀어붙이는 힘과 강단으로 봐요. 힘이 넘치는 만큼 쉬는 때를 정해두고 페이스를 조절하면 좋아요."},"goegang":{"name":"괴강살","hanja":"魁罡殺","title":"앞장서는 배짱","body":"북두칠성의 머리를 뜻하는 기운으로, 리더십과 배짱이 강한 성향이에요. 스스로 판단하고 앞장서는 힘이 있어 책임 있는 자리에서 빛나기 쉬워요. 고집이 세 보일 수 있으니 다른 의견을 들어보는 여유를 곁들이면 좋아요."},"gongmang":{"name":"공망","hanja":"空亡","title":"비어 있어 자유로운 자리","body":"공망은 \"비어 있다\"는 뜻으로, 그 자리의 일은 기대보다 결과가 늦게 따라오기 쉬운 기운이에요. 대신 욕심을 내려놓게 되어 정신적인 가치나 새로운 관점에 마음이 열리는 편이에요. 해당 자리의 일은 조급해하지 말고 길게 보면 좋아요."}}$json$::jsonb, 1)
